using System.ComponentModel.DataAnnotations;
using System.Globalization;
using System.Security.Cryptography;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.WebUtilities;
using Microsoft.EntityFrameworkCore;
using Osynix.Ats.Data;
using Osynix.Ats.Domain;
namespace Osynix.Ats.Services;
public record InterviewInvite(Guid AssessmentId,Guid ApplicationRevision,Guid? InterviewId,Guid? InterviewRevision,string CandidateEmail,string ManagerEmail,string LocalStart,string TimeZone,int DurationMinutes,string Mode,string Provider,string MeetingLink,string Location,string Message);
public record InterviewResponse(Guid InterviewId,Guid Revision,string Response,string Notes,string? LocalStart,string TimeZone);
public record InterviewResult(string Link,string Message);
public class InterviewService(IDbContextFactory<AtsDbContext> factory,Access access,IDataProtectionProvider protection,IConfiguration config,IAccountEmail email,RecruitmentUpdates updates){
 public const string CookieName="Osynix.Interview";
 readonly IDataProtector tokens=protection.CreateProtector("Osynix.Interview.Token.v1");
 readonly IDataProtector cookies=protection.CreateProtector("Osynix.Interview.Cookie.v1");
 public bool CanEmail=>email.Configured&&Uri.TryCreate(config["Review:PublicBaseUrl"],UriKind.Absolute,out var u)&&u.Scheme=="https"&&!u.IsLoopback;
 string BaseUrl=>Uri.TryCreate(config["Review:PublicBaseUrl"],UriKind.Absolute,out var u)&&u.Scheme=="https"?u.GetLeftPart(UriPartial.Authority):"http://localhost:5080";
 static string Hash(string token)=>Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(token)));
 public static DateTime ParseTime(string? localStart,string zoneId){
  TimeZoneInfo zone;try{zone=TimeZoneInfo.FindSystemTimeZoneById(zoneId);}catch{throw new InvalidOperationException("Choose A Valid Time Zone.");}
  if(!DateTime.TryParseExact(localStart,["yyyy-MM-ddTHH:mm","yyyy-MM-ddTHH:mm:ss"],CultureInfo.InvariantCulture,DateTimeStyles.None,out var local)||zone.IsInvalidTime(local)||zone.IsAmbiguousTime(local))throw new InvalidOperationException("Choose An Unambiguous Local Date And Time.");
  var utc=TimeZoneInfo.ConvertTimeToUtc(DateTime.SpecifyKind(local,DateTimeKind.Unspecified),zone);if(utc<=DateTime.UtcNow||utc>DateTime.UtcNow.AddYears(1))throw new InvalidOperationException("Choose A Future Interview Time Within One Year.");return utc;
 }
 public static string When(DateTime utc,string zone){try{return TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(utc,DateTimeKind.Utc),TimeZoneInfo.FindSystemTimeZoneById(zone)).ToString("dddd, dd MMM yyyy · HH:mm")+" · "+zone;}catch{return utc.ToString("u");}}
 public static InterviewSummary Summary(InterviewBooking i)=>new(i.Id,i.Revision,i.AssessmentId,i.Status,i.StartUtc,i.DurationMinutes,i.TimeZone,i.Mode,i.Provider,i.MeetingLink,i.Location,i.ProposedStartUtc,i.ProposedTimeZone,ReportService.ClientSafeText(i.ResponseNotes),i.ResponseSource);
 public async Task<List<InterviewSummary>> List(){var ids=(await new AtsService(factory,access).Assessments()).Select(a=>a.Id).ToList();await using var db=await factory.CreateDbContextAsync();return (await db.InterviewBookings.AsNoTracking().Where(i=>ids.Contains(i.AssessmentId)).OrderByDescending(i=>i.CreatedUtc).ToListAsync()).Select(Summary).ToList();}
 public async Task<InterviewBooking?> Details(Guid assessmentId){await access.RequireApplication(assessmentId);await using var db=await factory.CreateDbContextAsync();return await db.InterviewBookings.AsNoTracking().Where(i=>i.AssessmentId==assessmentId).OrderByDescending(i=>i.CreatedUtc).FirstOrDefaultAsync();}
 public async Task<string> DefaultManagerEmail(Guid assessmentId){await access.RequireApplication(assessmentId);await using var db=await factory.CreateDbContextAsync();var sub=await db.HiringSubmissions.Where(s=>s.AssessmentId==assessmentId&&!s.Revoked).OrderByDescending(s=>s.SubmittedUtc).FirstOrDefaultAsync();var contact=sub is null?null:await db.ClientContacts.FindAsync(sub.ContactId);if(!string.IsNullOrWhiteSpace(contact?.Email))return contact.Email;return await db.Assessments.Where(a=>a.Id==assessmentId).Select(a=>a.Position!.HiringManagerEmail).SingleAsync();}
 static void EmailAddress(string address,bool required){if(address.Length>320||(address.Length>0&&!new EmailAddressAttribute().IsValid(address))||required&&address.Length==0)throw new InvalidOperationException("Enter A Valid Candidate Email And An Optional Hiring Manager Email.");}
 static async Task EnsureActive(AtsDbContext db,Assessment a,bool allowOffer=false){var p=await db.Positions.SingleAsync(p=>p.Id==a.PositionId);if(a.State!="Saved"||(a.Stage is "Rejected" or "Hired")||a.Stage=="Offer Sent"&&!allowOffer||p.Status is not("Active" or "On Hold"))throw new InvalidOperationException("This Application Is No Longer Available For Interview Changes.");}
 public async Task<InterviewResult> Invite(InterviewInvite input){
  if(input.CandidateEmail is null||input.ManagerEmail is null||input.TimeZone is null||input.Message is null||input.Location is null||input.MeetingLink is null)throw new InvalidOperationException("Complete The Interview Fields.");
  await access.RequireApplication(input.AssessmentId);EmailAddress(input.CandidateEmail.Trim(),true);EmailAddress(input.ManagerEmail.Trim(),false);
  var start=ParseTime(input.LocalStart,input.TimeZone);if(input.DurationMinutes is <15 or >240||input.Mode is not("Online" or "On-Site")||input.Message.Length>5000||input.Location.Length>1000||input.MeetingLink.Length>2000)throw new InvalidOperationException("Check The Interview Format, Duration And Message Length.");
  if(input.Mode=="Online"&&(!Uri.TryCreate(input.MeetingLink,UriKind.Absolute,out var uri)||uri.Scheme!="https"||!string.IsNullOrEmpty(uri.UserInfo)))throw new InvalidOperationException("Add A Valid HTTPS Meeting Link From Google Meet, Teams, Zoom Or Another Provider.");
  if(input.Mode=="On-Site"&&string.IsNullOrWhiteSpace(input.Location))throw new InvalidOperationException("Add The On-Site Address And Arrival Instructions.");
  if(input.Provider is not("Manual Link" or "Google Meet" or "Microsoft Teams" or "Zoom"))throw new InvalidOperationException("Choose A Meeting Provider.");
  await using var db=await factory.CreateDbContextAsync();await using var tx=await db.Database.BeginTransactionAsync();var a=await db.Assessments.Include(a=>a.Position).SingleAsync(a=>a.Id==input.AssessmentId);await EnsureActive(db,a);if(a.Revision!=input.ApplicationRevision)throw new DbUpdateConcurrencyException("The Application Changed. Reopen It Before Sending.");
  var sub=await (from s in db.HiringSubmissions join g in db.HiringReviewGrants on s.GrantId equals g.Id where s.AssessmentId==a.Id&&!s.Revoked&&!g.Revoked&&g.ExpiresUtc>DateTime.UtcNow orderby s.SubmittedUtc descending select s).FirstOrDefaultAsync()??throw new InvalidOperationException("Submit This Profile For Hiring Manager Review First.");
  var i=await db.InterviewBookings.Where(i=>i.AssessmentId==a.Id).OrderByDescending(i=>i.CreatedUtc).FirstOrDefaultAsync();
  if(input.InterviewId.HasValue){if(i?.Id!=input.InterviewId||i.Revision!=input.InterviewRevision)throw new DbUpdateConcurrencyException("The Interview Changed. Reopen It Before Sending.");if(i.Status=="Completed")i=null;}
  else if(i is not null)throw new DbUpdateConcurrencyException("An Interview Already Exists. Reopen It Before Sending.");
  if(i is null){i=new(){AssessmentId=a.Id};db.Add(i);}else await CancelPendingMail(db,i.Id);
  i.SubmissionId=sub.Id;i.OrganizerId=await access.UserId();i.CandidateEmail=input.CandidateEmail.Trim();i.ManagerEmail=input.ManagerEmail.Trim();if(i.ManagerEmail.Length==0){var contact=await db.ClientContacts.FindAsync(sub.ContactId);i.ManagerEmail=!string.IsNullOrWhiteSpace(contact?.Email)?contact.Email.Trim():a.Position!.HiringManagerEmail.Trim();EmailAddress(i.ManagerEmail,false);}i.StartUtc=start;i.TimeZone=input.TimeZone;i.DurationMinutes=input.DurationMinutes;i.Mode=input.Mode;i.Provider=input.Mode=="Online"?input.Provider:"On-Site";i.MeetingLink=input.Mode=="Online"?input.MeetingLink.Trim():"";i.Location=input.Mode=="On-Site"?input.Location.Trim():"";i.Message=input.Message.Trim();i.Status="Awaiting Confirmation";i.ProposedStartUtc=null;i.ProposedTimeZone="";i.ResponseNotes="";i.ResponseSource="";i.RespondedUtc=null;Rotate(i);
  a.Stage="Client Interview";a.ClientStatus="Client Interview";a.InterviewStatus="Not Scheduled";await TaskFor(db,i,a,"Review Feedback","Interview Invitation Prepared","Awaiting Candidate Confirmation");await QueueMessages(db,i,a,"Interview Invitation",true);AtsService.Audit(db,i.OrganizerId,"Interview invitation prepared",i.Id.ToString(),$"{i.Mode} · {i.StartUtc:u}",a.CandidateId,a.Id);await db.SaveChangesAsync();await tx.CommitAsync();updates.Publish();return new(Link(i),await Deliver(i.Id));
 }
 void Rotate(InterviewBooking i){var token=WebEncoders.Base64UrlEncode(RandomNumberGenerator.GetBytes(32));i.TokenHash=Hash(token);i.ProtectedToken=tokens.Protect(token);i.ExpiresUtc=i.StartUtc.AddDays(7);}
 string Link(InterviewBooking i)=>BaseUrl+"/interview/access?token="+Uri.EscapeDataString(tokens.Unprotect(i.ProtectedToken));
 public async Task<string> ResponseLink(Guid id){await using var db=await factory.CreateDbContextAsync();var i=await db.InterviewBookings.SingleAsync(i=>i.Id==id);await access.RequireApplication(i.AssessmentId);return Link(i);}
 public async Task<(string Cookie,DateTime Expires)?> Exchange(string token){if(token.Length is <30 or >200)return null;await using var db=await factory.CreateDbContextAsync();var hash=Hash(token);var i=await db.InterviewBookings.SingleOrDefaultAsync(i=>i.TokenHash==hash&&i.ExpiresUtc>DateTime.UtcNow);return i is null?null:(cookies.Protect(i.Id+":"+i.TokenHash),i.ExpiresUtc);}
 async Task<InterviewBooking> FromCookie(AtsDbContext db,string? cookie){Guid id;string hash;try{var values=cookies.Unprotect(cookie??"").Split(':');id=Guid.Parse(values[0]);hash=values[1];}catch{throw new UnauthorizedAccessException("This Invitation Is Invalid Or Expired.");}var i=await db.InterviewBookings.SingleOrDefaultAsync(i=>i.Id==id&&i.TokenHash==hash&&i.ExpiresUtc>DateTime.UtcNow)??throw new UnauthorizedAccessException("This Invitation Is Invalid Or Expired.");if(!await db.HiringSubmissions.AnyAsync(s=>s.Id==i.SubmissionId&&!s.Revoked&&db.HiringReviewGrants.Any(g=>g.Id==s.GrantId&&!g.Revoked&&g.ExpiresUtc>DateTime.UtcNow)))throw new UnauthorizedAccessException("This Invitation Has Been Withdrawn.");return i;}
 public async Task<object> Read(string? cookie){await using var db=await factory.CreateDbContextAsync();var i=await FromCookie(db,cookie);var a=await db.Assessments.Include(a=>a.Position).SingleAsync(a=>a.Id==i.AssessmentId);return new{interview=Summary(i),candidate=a.CandidateName,position=a.Position!.Title,company=a.Position.Client,message=i.Message,canRespond=(a.Stage is not("Rejected" or "Hired" or "Offer Sent"))&&(a.Position.Status is "Active" or "On Hold")&&i.StartUtc>DateTime.UtcNow&&(i.Status is "Awaiting Confirmation" or "Confirmed")};}
 public async Task Respond(string? cookie,InterviewResponse input){await using var db=await factory.CreateDbContextAsync();var i=await FromCookie(db,cookie);if(i.Id!=input.InterviewId)throw new UnauthorizedAccessException();await RespondCore(db,i,input,"Candidate Via Invitation",null);}
 public async Task RecordResponse(InterviewResponse input,string channel){if(channel is not("Phone" or "WhatsApp" or "Email" or "Other"))throw new InvalidOperationException("Choose How The Response Was Received.");await using var db=await factory.CreateDbContextAsync();var i=await db.InterviewBookings.SingleAsync(i=>i.Id==input.InterviewId);await access.RequireApplication(i.AssessmentId);await RespondCore(db,i,input,"Recorded By Recruiter · "+channel,await access.UserId());}
 async Task RespondCore(AtsDbContext db,InterviewBooking i,InterviewResponse input,string source,string? actor){
  await using var tx=await db.Database.BeginTransactionAsync();var a=await db.Assessments.SingleAsync(a=>a.Id==i.AssessmentId);await EnsureActive(db,a);if(!await db.HiringSubmissions.AnyAsync(s=>s.Id==i.SubmissionId&&!s.Revoked&&db.HiringReviewGrants.Any(g=>g.Id==s.GrantId&&!g.Revoked&&g.ExpiresUtc>DateTime.UtcNow)))throw new InvalidOperationException("This Interview Sharing Link Was Revoked.");if(i.Revision!=input.Revision)throw new DbUpdateConcurrencyException("This Interview Changed. Refresh Before Responding.");if(i.Status is not("Awaiting Confirmation" or "Confirmed")||i.StartUtc<=DateTime.UtcNow)throw new InvalidOperationException("This Invitation Cannot Receive A Response Now.");if(input.Response is not("Accepted" or "Declined" or "New Time Proposed")||input.Notes is null||input.Notes.Length>2000)throw new InvalidOperationException("Choose A Response And Keep Notes Within 2,000 Characters.");
  i.ProposedStartUtc=input.Response=="New Time Proposed"?ParseTime(input.LocalStart,input.TimeZone):null;i.ProposedTimeZone=i.ProposedStartUtc.HasValue?input.TimeZone:"";i.Status=input.Response=="Accepted"?"Confirmed":input.Response;i.ResponseNotes=ReportService.ClientSafeText(input.Notes.Trim());i.ResponseSource=source;i.RespondedUtc=DateTime.UtcNow;
  a.InterviewStatus=i.Status=="Confirmed"?"Scheduled":"Reschedule Required";a.Stage="Client Interview";a.ClientStatus="Client Interview";await TaskFor(db,i,a,i.Status=="Declined"?"Arrange Interview":"Review Feedback",i.Status=="Declined"?"Candidate Declined Interview":i.Status=="New Time Proposed"?"Hiring Manager To Review Proposed Time":"Interview Confirmed",i.Status);await CancelPendingMail(db,i.Id);await QueueMessages(db,i,a,"Interview "+i.Status,true);AtsService.Audit(db,actor??"Candidate","Interview response",i.Id.ToString(),source+": "+i.Status,a.CandidateId,a.Id);await db.SaveChangesAsync();await tx.CommitAsync();updates.Publish();await Deliver(i.Id);
 }
 public async Task ReviewProposal(Guid assessmentId,Guid id,Guid revision,bool accept,string? localStart,string zone){
  await using var db=await factory.CreateDbContextAsync();await using var tx=await db.Database.BeginTransactionAsync();var i=await db.InterviewBookings.SingleOrDefaultAsync(i=>i.Id==id&&i.AssessmentId==assessmentId)??throw new UnauthorizedAccessException();var a=await db.Assessments.SingleAsync(a=>a.Id==assessmentId);await EnsureActive(db,a);if(i.Revision!=revision)throw new DbUpdateConcurrencyException("This Interview Changed. Refresh Before Responding.");if(i.Status!="New Time Proposed"||i.ProposedStartUtc is null)throw new InvalidOperationException("No Candidate Time Proposal Is Awaiting Review.");
  i.StartUtc=accept?i.ProposedStartUtc.Value:ParseTime(localStart,zone);if(i.StartUtc<=DateTime.UtcNow)throw new InvalidOperationException("Choose A Future Interview Time.");i.TimeZone=accept?i.ProposedTimeZone:zone;i.Status=accept?"Confirmed":"Awaiting Confirmation";i.ProposedStartUtc=null;i.ProposedTimeZone="";i.ResponseSource="Hiring Manager Via Review Link";Rotate(i);a.Stage="Client Interview";a.ClientStatus="Client Interview";a.InterviewStatus=accept?"Scheduled":"Not Scheduled";await TaskFor(db,i,a,"Review Feedback",accept?"Proposed Interview Time Accepted":"Alternative Interview Time Sent",i.Status);await CancelPendingMail(db,i.Id);await QueueMessages(db,i,a,accept?"Proposed Interview Time Accepted":"Alternative Interview Time Proposed",true);AtsService.Audit(db,"HiringManager","Interview proposal reviewed",i.Id.ToString(),i.Status,a.CandidateId,a.Id);await db.SaveChangesAsync();await tx.CommitAsync();updates.Publish();await Deliver(i.Id);
 }
 public async Task Progress(Guid assessmentId,Guid revision,string outcome,string notes){await access.RequireApplication(assessmentId);if(outcome is not("Hold" or "Reject" or "Hired" or "Offer Sent" or "Interview Completed" or "Next Round")||notes is null||notes.Length>5000)throw new InvalidOperationException("Choose A Valid Outcome.");await using var db=await factory.CreateDbContextAsync();await using var tx=await db.Database.BeginTransactionAsync();var a=await db.Assessments.SingleAsync(a=>a.Id==assessmentId);await EnsureActive(db,a,true);if(a.Revision!=revision)throw new DbUpdateConcurrencyException("The Application Changed. Reopen It Before Saving.");var i=await db.InterviewBookings.Where(i=>i.AssessmentId==a.Id).OrderByDescending(i=>i.CreatedUtc).FirstOrDefaultAsync();if(outcome=="Interview Completed"&&(i?.Status!="Confirmed"||i.StartUtc>DateTime.UtcNow))throw new InvalidOperationException("Only A Confirmed Interview That Has Started Can Be Marked Completed.");
  if(outcome=="Next Round"&&(i is null||i.Status!="Completed"))throw new InvalidOperationException("Complete The Current Interview Before Starting Another Round.");
  a.RecruiterNotes=notes.Trim();a.Stage=outcome switch{"Reject"=>"Rejected","Interview Completed"=>"Client Interview","Next Round"=>"Interview Requested",_=>outcome};a.ClientStatus=outcome switch{"Reject"=>"Client Rejected","Hired"=>"Hired","Offer Sent"=>"Offer","Next Round"=>"Interview Requested",_=>"Under Review"};a.InterviewStatus=outcome=="Interview Completed"?"Completed":outcome=="Next Round"?"Not Scheduled":"Not Required";
  if(i is not null&&i.Status is not("Completed" or "Cancelled")){i.Status=outcome is "Interview Completed" or "Next Round"?"Completed":"Cancelled";await CancelPendingMail(db,i.Id);if(i.Status=="Cancelled")await QueueMessages(db,i,a,"Interview Cancelled",true);}
  var sub=await db.HiringSubmissions.Where(s=>s.AssessmentId==a.Id&&!s.Revoked).OrderByDescending(s=>s.SubmittedUtc).FirstOrDefaultAsync();if(sub is not null){sub.Feedback=outcome=="Reject"?"Reject":outcome=="Next Round"?"Request Interview":outcome=="Interview Completed"?"Awaiting Feedback":outcome;sub.FeedbackUtc=DateTime.UtcNow;await RecruiterActionService.Capture(db,sub,a);if(outcome=="Interview Completed"){a.Stage="Awaiting Client Feedback";a.ClientStatus="Submitted";}}
  if(i is not null&&i.Status=="Completed")await QueueMessages(db,i,a,outcome=="Interview Completed"?"Interview Feedback Requested":"Recruitment Update — "+outcome,false);
  AtsService.Audit(db,await access.UserId(),"Pipeline outcome updated",a.Id.ToString(),outcome,a.CandidateId,a.Id);await db.SaveChangesAsync();await tx.CommitAsync();updates.Publish();if(i is not null)await Deliver(i.Id);
 }
 internal async Task CancelForFeedback(AtsDbContext db,InterviewBooking i,Assessment a){i.Status="Cancelled";await CancelPendingMail(db,i.Id);await QueueMessages(db,i,a,"Interview Cancelled",true);}
 internal Task<string> FlushQueued(Guid id)=>Deliver(id);
 static async Task TaskFor(AtsDbContext db,InterviewBooking i,Assessment a,string type,string title,string feedback){var sub=await db.HiringSubmissions.SingleAsync(s=>s.Id==i.SubmissionId);await RecruiterActionService.Capture(db,sub,a);var task=db.RecruiterActions.Local.Single(t=>t.AssessmentId==a.Id);task.Type=type;task.Title=title;task.Feedback=feedback;task.Remarks=i.ResponseNotes;task.FeedbackUtc=DateTime.UtcNow;}
 static async Task CancelPendingMail(AtsDbContext db,Guid id){foreach(var m in await db.InterviewDeliveries.Where(m=>m.InterviewId==id&&m.Status!="Sent"&&m.Status!="Superseded").ToListAsync())m.Status="Superseded";}
 async Task QueueMessages(AtsDbContext db,InterviewBooking i,Assessment a,string subject,bool candidate){
  var p=await db.Positions.SingleAsync(p=>p.Id==a.PositionId);var details=$"{a.CandidateName} — {p.Title}\n{p.Client}\n\nStatus: {i.Status}\nRecruitment Update: {a.Stage}\n{When(i.StartUtc,i.TimeZone)}\nDuration: {i.DurationMinutes} minutes\n{i.Mode}\n"+(i.Mode=="Online"?"Meeting: "+i.MeetingLink:"Address: "+i.Location)+"\n\n"+i.Message;
  if(i.ProposedStartUtc is DateTime proposed)details+="\n\nCandidate Proposed: "+When(proposed,i.ProposedTimeZone);
  if(candidate)db.Add(new InterviewDelivery{InterviewId=i.Id,Recipient=i.CandidateEmail,Subject="Osynix — "+subject+" · "+p.Title,Body=details+"\n\nConfirm, Decline Or Propose A New Time:\n"+Link(i)});
  if(i.ManagerEmail.Length==0){var shared=await db.HiringSubmissions.SingleAsync(s=>s.Id==i.SubmissionId);var contact=await db.ClientContacts.FindAsync(shared.ContactId);var fallback=!string.IsNullOrWhiteSpace(contact?.Email)?contact.Email.Trim():p.HiringManagerEmail.Trim();if(fallback.Length>0&&new EmailAddressAttribute().IsValid(fallback))i.ManagerEmail=fallback;}
  if(i.ManagerEmail.Length>0){var sub=await db.HiringSubmissions.SingleAsync(s=>s.Id==i.SubmissionId);var grant=await db.HiringReviewGrants.SingleAsync(g=>g.Id==sub.GrantId);var reviewToken=protection.CreateProtector("Osynix.HiringReview.Token.v1").Unprotect(grant.ProtectedToken);db.Add(new InterviewDelivery{InterviewId=i.Id,Recipient=i.ManagerEmail,Subject="Osynix — "+subject+" · "+p.Title,Body=details+"\n\nReview Interview Updates:\n"+BaseUrl+"/review/access?token="+Uri.EscapeDataString(reviewToken)+"&position="+p.Id});}
 }
 public async Task Reopen(Guid assessmentId,Guid revision){await access.RequireApplication(assessmentId);await using var db=await factory.CreateDbContextAsync();var a=await db.Assessments.SingleAsync(a=>a.Id==assessmentId);if(a.Revision!=revision)throw new DbUpdateConcurrencyException("The Application Changed.");if(a.Stage!="Rejected")throw new InvalidOperationException("Only Rejected Applications Can Be Reopened Here.");a.Stage="Shortlisted";a.ClientStatus="Not Submitted";a.InterviewStatus="Not Scheduled";foreach(var s in await db.HiringSubmissions.Where(s=>s.AssessmentId==a.Id).ToListAsync())s.Revoked=true;AtsService.Audit(db,await access.UserId(),"Rejected application reopened",a.Id.ToString(),"Explicit Resubmission Required",a.CandidateId,a.Id);await db.SaveChangesAsync();updates.Publish();}
 public async Task<string> RetryDelivery(Guid id){await using var db=await factory.CreateDbContextAsync();var i=await db.InterviewBookings.SingleAsync(i=>i.Id==id);await access.RequireApplication(i.AssessmentId);return await Deliver(id);}
 public async Task<string> DeliveryStatus(Guid id){await using var db=await factory.CreateDbContextAsync();var i=await db.InterviewBookings.SingleAsync(i=>i.Id==id);await access.RequireApplication(i.AssessmentId);var states=await db.InterviewDeliveries.Where(m=>m.InterviewId==id&&m.Status!="Superseded").Select(m=>m.Status).ToListAsync();return states.Count>0&&states.All(s=>s=="Sent")?"Email Sent":states.Any(s=>s=="Failed")?"Email Delivery Failed — Retry Available":!CanEmail?"Email Not Sent — Public HTTPS And Email Configuration Required":states.Any(s=>s=="Sending")?"Sending Email Updates":"Email Updates Queued — Retry Available";}
 async Task<string> Deliver(Guid id){
  if(!CanEmail)return "Saved. Email Not Sent: Configure Public HTTPS And Email Delivery. Copy The Response Link For Local Testing.";
  await using var db=await factory.CreateDbContextAsync();var stale=DateTime.UtcNow.AddMinutes(-2);
  var messages=await db.InterviewDeliveries.AsNoTracking().Where(m=>m.InterviewId==id&&(m.Status=="Pending"||m.Status=="Failed"||m.Status=="Sending"&&m.UpdatedUtc<stale)).ToListAsync();
  foreach(var m in messages){
   var claimed=await db.InterviewDeliveries.Where(x=>x.Id==m.Id&&(x.Status=="Pending"||x.Status=="Failed"||x.Status=="Sending"&&x.UpdatedUtc<stale)).ExecuteUpdateAsync(set=>set.SetProperty(x=>x.Status,"Sending").SetProperty(x=>x.UpdatedUtc,DateTime.UtcNow));if(claimed!=1)continue;
   try{await email.Send(m.Recipient,m.Subject,m.Body);await db.InterviewDeliveries.Where(x=>x.Id==m.Id&&x.Status=="Sending").ExecuteUpdateAsync(set=>set.SetProperty(x=>x.Status,"Sent").SetProperty(x=>x.SentUtc,DateTime.UtcNow).SetProperty(x=>x.UpdatedUtc,DateTime.UtcNow));}
   catch{await db.InterviewDeliveries.Where(x=>x.Id==m.Id&&x.Status=="Sending").ExecuteUpdateAsync(set=>set.SetProperty(x=>x.Status,"Failed").SetProperty(x=>x.UpdatedUtc,DateTime.UtcNow));}
  }
  updates.Publish();return await db.InterviewDeliveries.AnyAsync(m=>m.InterviewId==id&&m.Status=="Failed")?"Saved. Some Emails Failed. Retry Delivery From The Interview Panel.":"Interview Updates Saved And Emails Sent.";
 }
}
